circle.setAttribute('cy',yScale(row.point.value));
circle.style.display='block';
});
var rowsHtml=rows.map(function(row){
return "<div class='pbi-tooltip-row'><span style='color:"+row.metric.color+"'>"+row.metric.label+"</span><strong>"+formatValue(row.point.value)+"</strong></div>";
}).join('');
tooltip.innerHTML="<div class='pbi-tooltip-time'>"+formatTime(basePoint.time)+"</div>"+rowsHtml;
tooltip.style.display='block';
var wrap=container.querySelector('.pbi-chart-wrap');
var wrapRect=wrap.getBoundingClientRect();
var tX=ev.clientX-wrapRect.left+14;
var tY=ev.clientY-wrapRect.top-36;
if(tX+tooltip.offsetWidth+16>wrapRect.width){tX=ev.clientX-wrapRect.left-tooltip.offsetWidth-14;}
if(tY<0){tY=ev.clientY-wrapRect.top+14;}
tooltip.style.left=Math.max(8,tX)+'px';
tooltip.style.top=Math.max(8,tY)+'px';
});
overlay.addEventListener('mouseleave',function(){
hoverLine.style.display='none';
tooltip.style.display='none';
METRICS.forEach(function(metric){
var circle=container.querySelector('#pbi-hover-point-'+metric.key);
if(circle)circle.style.display='none';
});
});
}
function renderEmpty(message){
container.innerHTML="<div class='pbi-panel'><div class='pbi-empty'>"+message+"</div></div>";
}
if(!data||!data.series||data.series.length===0||data.state!=='Done'){renderEmpty('Aguardando dados...');return;}
var metrics=parseData(data);
var hasData=METRICS.some(function(m){return metrics[m.key].length>0;});
if(!hasData){renderEmpty('Nenhum dado foi encontrado para este per\u00edodo.');return;}
var legendHtml=METRICS.map(function(m){
return "<span><i class='pbi-dot' style='background:"+m.color+"'></i> "+escapeHTML(m.label)+"</span>";
}).join('');
container.innerHTML="<div class='pbi-panel'><div class='pbi-panel-title'><div class='pbi-panel-title-left'><span class='pbi-panel-icon' style='color:#10B981'>"+PANEL_ICON+"</span><strong>"+escapeHTML(PANEL_TITLE)+"</strong></div><div class='pbi-legend'>"+legendHtml+"</div></div><div class='pbi-chart-wrap'></div></div>";
renderChart(metrics);
if(typeof ResizeObserver!=='undefined'){
if(container.__pbiResizeObserver)container.__pbiResizeObserver.disconnect();
var resizeTimer=null;
var chartWrap=container.querySelector('.pbi-chart-wrap');
container.__pbiResizeObserver=new ResizeObserver(function(){
clearTimeout(resizeTimer);
resizeTimer=setTimeout(function(){renderChart(metrics);},120);
});
if(chartWrap)container.__pbiResizeObserver.observe(chartWrap);
}
})();

options.css:
/* =========================================================
   ROUTING ENGINE - CPU / MEMORIA / SWAP / DISCO
========================================================= */

#routing-resource-panel {
    --bg: #0d1218;

    --surface: rgba(255, 255, 255, 0.045);
    --surface-strong: rgba(255, 255, 255, 0.065);

    --border: rgba(255, 255, 255, 0.09);
    --border-soft: rgba(255, 255, 255, 0.055);

    --text: #f4f7fb;
    --muted: #8d98a6;

    --blue: #4c9ac5;
    --green: #22c55e;

    --yellow: #facc15;
    --red: #ef4444;

    width: 100%;
    height: 100%;
    min-height: 190px;

    box-sizing: border-box;
    padding: 10px;

    font-family: "Inter", sans-serif;
    color: var(--text);

    background:
        radial-gradient(
            circle at 0% 0%,
            rgba(76, 154, 197, 0.12),
            transparent 34%
        ),
        radial-gradient(
            circle at 100% 100%,
            rgba(79, 165, 116, 0.08),
            transparent 30%
        ),
        linear-gradient(
            135deg,
            #11171e 0%,
            #0b1016 100%
        );

    border-radius: 14px;

    overflow: hidden;
    container-type: size;
}

#routing-resource-panel * {
    box-sizing: border-box;
}


/* =========================================================
   ROOT
========================================================= */

.rr-root {
    width: 100%;
    height: 100%;
    min-height: 0;

    position: relative;

    display: grid;
    grid-template-rows: auto minmax(0, 1fr);

    gap: 10px;

    overflow: hidden;
}


/* =========================================================
   HEADER
========================================================= */

.rr-header {
    position: relative;

    min-width: 0;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 10px;

    padding-bottom: 8px;

    border-bottom:
        1px solid var(--border-soft);
}

.rr-header-left {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 9px;
}

.rr-header-icon {
    width: 34px;
    height: 34px;

    flex-shrink: 0;

    display: grid;
    place-items: center;

    border-radius: 10px;

    color: var(--blue);

    background:
        rgba(76, 154, 197, 0.12);

    border:
        1px solid rgba(76, 154, 197, 0.23);
}

.rr-header-icon svg {
    width: 16px;
    height: 16px;
    display: block;
}

.rr-header-text {
    min-width: 0;
}

.rr-header-text strong {
    display: block;

    color: #ffffff;

    font-size: 14px;
    font-weight: 900;

    line-height: 1.1;

    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.rr-header-text span {
    display: block;

    margin-top: 3px;

    color: var(--muted);

    font-size: 8px;
    font-weight: 800;

    text-transform: uppercase;
    letter-spacing: 0.04em;

    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}


/* =========================================================
   A?.ES DO HEADER
========================================================= */

.rr-actions {
    flex-shrink: 0;

    display: flex;
    align-items: center;

    gap: 8px;
}

.rr-refresh {
    flex-shrink: 0;

    font-family:
        "Roboto Mono",
        monospace;

    font-size: 11px;
    font-weight: 700;

    color: var(--muted);

    padding: 7px 10px;

    border-radius: 999px;

    background:
        var(--surface);

    border:
        1px solid var(--border);

    white-space: nowrap;
}

.rr-insight-btn {
    flex-shrink: 0;

    width: 34px;
    height: 34px;

    padding: 0;

    border-radius: 10px;

    cursor: pointer;

    display: grid;
    place-items: center;

    color: var(--yellow);

    background:
        rgba(210, 166, 79, 0.10);

    border:
        1px solid rgba(210, 166, 79, 0.28);

    transition: background 0.2s ease;
}

.rr-insight-btn:hover {
    background:
        rgba(210, 166, 79, 0.18);
}

.rr-insight-btn svg {
    width: 15px;
    height: 15px;
    display: block;
}

.rr-insight-popover {
    position: absolute;
    z-index: 9999;

    display: none;

    top: 40px;
    right: 0;

    width: min(240px, 80vw);

    padding: 10px;

    border-radius: 10px;

    background:
        rgba(15, 22, 33, 0.98);

    border:
        1px solid rgba(210, 166, 79, 0.24);

    box-shadow:
        0 14px 34px
        rgba(0, 0, 0, 0.50);
}

.rr-insight-popover.open {
    display: block;
}

.rr-insight-popover strong {
    display: block;

    color: #ffffff;

    font-size: 9.5px;
    font-weight: 900;

    margin-bottom: 4px;
}

.rr-insight-popover span {
    display: block;

    color: var(--muted);

    font-size: 8.5px;
    font-weight: 600;

    line-height: 1.5;
}


/* =========================================================
   GRID
========================================================= */

.rr-grid {
    min-width: 0;
    min-height: 0;

    display: grid;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 10px;
}


/* =========================================================
   CARD
========================================================= */

.rr-resource {
    --resource-color: #38bdf8;
    --resource-rgb: 56, 189, 248;

    position: relative;

    min-width: 0;
    min-height: 0;

    display: grid;

    grid-template-rows:
        auto
        auto
        auto;

    gap: 8px;

    padding: 11px;

    border-radius: 15px;

    background:
        radial-gradient(
            circle at 88% 20%,
            rgba(var(--resource-rgb), 0.08),
            transparent 38%
        ),
        linear-gradient(
            145deg,
            rgba(255, 255, 255, 0.058),
            rgba(255, 255, 255, 0.024)
        );

    border:
        1px solid var(--border);

    overflow: hidden;

    isolation: isolate;
}

.rr-resource.cpu {
    --resource-color: #38bdf8;
    --resource-rgb: 56, 189, 248;
}

.rr-resource.mem {
    --resource-color: #a78bfa;
    --resource-rgb: 167, 139, 250;
}

.rr-resource.swap {
    --resource-color: #fb923c;
    --resource-rgb: 251, 146, 60;
}

.rr-resource.disk {
    --resource-color: #f472b6;
    --resource-rgb: 244, 114, 182;
}


/* BARRA SUPERIOR */

.rr-resource::before {
    content: "";

    position: absolute;

    top: 0;
    left: 0;
    right: 0;

    height: 3px;

    background:
        var(--resource-color);

    z-index: 3;
}


/* GLOW DE FUNDO */

.rr-resource::after {
    content: "";

    position: absolute;

    width: 180px;
    height: 180px;

    right: -75px;
    bottom: -110px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(var(--resource-rgb), 0.15),
            transparent 68%
        );

    animation:
        rrAmbientGlow
        5s ease-in-out infinite;

    pointer-events: none;

    z-index: 0;
}


/* =========================================================
   CABE?ALHO DO CARD
========================================================= */

.rr-resource-header {
    position: relative;
    z-index: 2;

    min-width: 0;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 8px;
}

.rr-resource-name {
    min-width: 0;

    display: flex;
    align-items: center;

    gap: 8px;
}

.rr-resource-icon {
    width: 26px;
    height: 26px;

    flex-shrink: 0;

    display: grid;
    place-items: center;

    border-radius: 8px;

    color:
        var(--resource-color);

    background:
        rgba(var(--resource-rgb), 0.12);

    border:
        1px solid rgba(var(--resource-rgb), 0.22);
}

.rr-resource-icon svg {
    width: 13px;
    height: 13px;
    display: block;
}

.rr-resource-title {
    min-width: 0;
}

.rr-resource-title strong {
    display: block;

    color: #ffffff;

    font-size: 10.5px;
    font-weight: 900;

    text-transform: uppercase;
    letter-spacing: 0.03em;

    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* =========================================================
   BADGE DE STATUS
========================================================= */

.rr-resource-status {
    flex-shrink: 0;

    display: inline-flex;
    align-items: center;

    padding: 4px 10px;

    border-radius: 999px;

    font-size: 10px;
    font-weight: 900;

    letter-spacing: 0.03em;

    text-transform: uppercase;
}

.rr-resource-status.ok {
    color: var(--green);

    background:
        rgba(34, 197, 94, 0.12);

    border:
        1px solid rgba(34, 197, 94, 0.24);
}

.rr-resource-status.warn {
    color: var(--yellow);

    background:
        rgba(250, 204, 21, 0.12);

    border:
        1px solid rgba(250, 204, 21, 0.24);
}

.rr-resource-status.bad {
    color: var(--red);

    background:
        rgba(239, 68, 68, 0.12);

    border:
        1px solid rgba(239, 68, 68, 0.24);
}

.rr-resource-status.unknown {
    color: var(--muted);

    background:
        rgba(141, 152, 166, 0.10);

    border:
        1px solid rgba(141, 152, 166, 0.22);
}


/* =========================================================
   BOTfO E POPOVER DE RESUMO DA M?TRICA
========================================================= */

.rr-metric-btn {
    flex-shrink: 0;

    width: 26px;
    height: 26px;

    padding: 0;

    border-radius: 8px;

    cursor: pointer;

    display: grid;
    place-items: center;

    color: var(--muted);

    background:
        rgba(255, 255, 255, 0.055);

    border:
        1px solid rgba(255, 255, 255, 0.12);

    transition: background 0.2s ease, color 0.2s ease;
}

.rr-metric-btn:hover {
    color: #ffffff;

    background:
        rgba(255, 255, 255, 0.12);
}

.rr-metric-btn svg {
    width: 13px;
    height: 13px;
    display: block;
}

.rr-metric-popover {
    position: absolute;
    z-index: 9999;

    display: none;

    width: 190px;

    padding: 10px;

    border-radius: 10px;

    background:
        rgba(15, 22, 33, 0.98);

    border:
        1px solid var(--border);

    box-shadow:
        0 14px 34px
        rgba(0, 0, 0, 0.50);
}

.rr-metric-popover.open {
    display: block;
}

.rr-metric-popover strong {
    display: block;

    color: #ffffff;

    font-size: 9.5px;
    font-weight: 900;

    margin-bottom: 6px;
}

.rr-metric-list {
    display: grid;

    gap: 6px;
}

.rr-metric-row {
    display: flex;
    justify-content: space-between;

    gap: 8px;

    padding: 6px 8px;

    border-radius: 7px;

    background:
        rgba(255, 255, 255, 0.04);

    border:
        1px solid rgba(255, 255, 255, 0.06);
}

.rr-metric-row span {
    font-size: 9px;

    color: var(--muted);
    font-weight: 800;

    text-transform: uppercase;
}

.rr-metric-row strong {
    margin: 0;

    font-family:
        "Roboto Mono",
        monospace;

    font-size: 10px;
    color: #ffffff;

    white-space: nowrap;
}


/* =========================================================
   CONTEsDO CENTRAL
========================================================= */

.rr-resource-main {
    position: relative;
    z-index: 2;

    min-width: 0;
    min-height: 0;

    display: grid;

    grid-template-columns:
        minmax(78px, 0.4fr)
        minmax(0, 1fr);

    gap: 10px;

    align-items: stretch;
}


/* =========================================================
   VALOR CENTRALIZADO
========================================================= */

.rr-value-area {
    min-width: 0;
    min-height: 0;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    gap: 12px;
}


.rr-gauge {
    --value: 0;

    width: 100%;
    height: 100%;

    max-width: 84px;
    max-height: 84px;

    aspect-ratio: 1 / 1;

    border-radius: 50%;

    display: grid;
    place-items: center;

    position: relative;

    background:
        radial-gradient(
            circle at center,
            #11171e 0 58%,
            transparent 59%
        ),
        conic-gradient(
            var(--resource-color) calc(var(--value) * 1%),
            rgba(255, 255, 255, 0.10) 0
        );
}

.rr-gauge::after {
    content: "";

    position: absolute;
    inset: 7px;

    border-radius: 50%;

    border:
        1px solid rgba(255, 255, 255, 0.08);
}

.rr-gauge-value {
    position: relative;
    z-index: 2;

    color: #ffffff;

    font-family:
        "Roboto Mono",
        monospace;

    font-size: clamp(
        14px,
        7cqh,
        22px
    );

    font-weight: 900;

    letter-spacing: -0.04em;
}

.rr-gauge-value small {
    margin-left: 1px;

    color:
        var(--resource-color);

    font-size: 0.5em;

    font-weight: 800;
}

/* =========================================================
   ANIMA?fO PRINCIPAL
========================================================= */

.rr-animation-area {
    position: relative;

    min-width: 0;
    min-height: 0;

    overflow: hidden;

    border-radius: 11px;

    background:
        linear-gradient(
            180deg,
            rgba(0, 0, 0, 0.16),
            rgba(0, 0, 0, 0.08)
        );

    border:
        1px solid rgba(255, 255, 255, 0.05);
}


/* LINHAS DE FUNDO */

.rr-animation-area::before {
    content: "";

    position: absolute;
    inset: 0;

    background:
        repeating-linear-gradient(
            to right,
            transparent 0,
            transparent 20px,
            rgba(255, 255, 255, 0.025) 21px
        );

    pointer-events: none;
}


/* SCANNER */

.rr-animation-area::after {
    content: "";

    position: absolute;

    top: 0;
    bottom: 0;

    width: 40px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(var(--resource-rgb), 0.10),
            rgba(var(--resource-rgb), 0.20),
            rgba(var(--resource-rgb), 0.10),
            transparent
        );

    filter: blur(2px);

    animation:
        rrSweep
        4s linear infinite;

    pointer-events: none;
}


/* =========================================================
   PULSE BARS
========================================================= */

.rr-pulse-grid {
    position: absolute;

    inset:
        10px 8px
        8px 8px;

    display: grid;

    grid-template-columns:
        repeat(16, minmax(3px, 1fr));

    align-items: end;

    gap: 3px;
}

.rr-pulse {
    position: relative;

    width: 100%;

    min-height: 8px;

    border-radius:
        3px 3px 2px 2px;

    background:
        rgba(255, 255, 255, 0.045);

    overflow: hidden;
}


/* BASE VISUAL */

.rr-pulse::before {
    content: "";

    position: absolute;

    left: 0;
    right: 0;
    bottom: 0;

    height:
        var(--base-height);

    border-radius: inherit;

    background:
        rgba(var(--resource-rgb), 0.17);
}


/* PULSO ATIVO */

.rr-pulse::after {
    content: "";

    position: absolute;

    left: 0;
    right: 0;
    bottom: 0;

    height:
        var(--pulse-height);

    border-radius: inherit;

    background:
        linear-gradient(
            to top,
            rgba(var(--resource-rgb), 0.62),
            var(--resource-color)
        );

    transform-origin:
        center bottom;

    animation:
        rrEqualizer
        var(--pulse-duration)
        ease-in-out
        infinite alternate;

    animation-delay:
        var(--pulse-delay);
}


/* =========================================================
   CURRENT VALUE LINE
========================================================= */

.rr-current-line {
    position: absolute;

    left: 8px;
    right: 8px;

    bottom:
        var(--current-level);

    height: 1px;

    background:
        rgba(var(--resource-rgb), 0.30);

    pointer-events: none;
}

.rr-current-line::before {
    content: "";

    position: absolute;

    left: 0;

    top: 50%;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background:
        var(--resource-color);

    transform:
        translate(-1px, -50%);

    box-shadow:
        0 0 8px
        rgba(var(--resource-rgb), 0.35);
}


/* =========================================================
   BARRA INFERIOR
========================================================= */

.rr-flow {
    position: relative;
    z-index: 2;

    min-width: 0;
}

.rr-flow-header {
    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 8px;

    margin-bottom: 5px;
}

.rr-flow-header span {
    color: var(--muted);

    font-size: 6.6px;
    font-weight: 800;

    text-transform: uppercase;
}

.rr-flow-header strong {
    color:
        var(--resource-color);

    font-family:
        "Roboto Mono",
        monospace;

    font-size: 7.8px;
    font-weight: 900;
}

.rr-flow-track {
    position: relative;

    width: 100%;
    height: 8px;

    border-radius: 999px;

    background:
        rgba(255, 255, 255, 0.07);

    border:
        1px solid rgba(255, 255, 255, 0.055);

    overflow: hidden;
}

.rr-flow-fill {
    position: relative;

    width:
        var(--resource-progress);

    height: 100%;

    border-radius: inherit;

    background:
        var(--resource-color);

    transition:
        width 0.8s
        cubic-bezier(
            0.22,
            1,
            0.36,
            1
        );

    overflow: hidden;
}


/* BRILHO MOVENDO */

.rr-flow-fill::after {
    content: "";

    position: absolute;

    top: 0;
    bottom: 0;

    width: 38px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255, 255, 255, 0.24),
            transparent
        );

    animation:
        rrFlowShine
        2.8s linear infinite;
}


/* =========================================================
   THRESHOLDS
========================================================= */

.rr-threshold {
    position: absolute;

    top: -2px;
    bottom: -2px;

    width: 1px;

    background:
        rgba(255, 255, 255, 0.20);

    z-index: 3;
}

.rr-threshold.t70 {
    left: 70%;
}

.rr-threshold.t90 {
    left: 90%;
}


/* =========================================================
   ESCALA
========================================================= */

.rr-scale {
    display: grid;

    grid-template-columns:
        70fr 20fr 10fr;

    margin-top: 4px;

    color: var(--muted);

    font-family:
        "Roboto Mono",
        monospace;

    font-size: 6px;
    font-weight: 700;
}

.rr-scale span:nth-child(1) {
    text-align: left;
}

.rr-scale span:nth-child(2) {
    text-align: left;
}

.rr-scale span:nth-child(3) {
    text-align: right;
}


/* =========================================================
   EMPTY
========================================================= */

.rr-empty {
    height: 100%;

    display: grid;
    place-items: center;

    color: var(--muted);

    font-size: 11px;
    font-weight: 700;

    border:
        1px dashed
        rgba(255, 255, 255, 0.14);

    border-radius: 12px;
}


/* =========================================================
   ANIMA?.ES
========================================================= */

@keyframes rrEqualizer {

    0% {
        transform:
            scaleY(0.65);

        filter:
            brightness(0.92);
    }

    100% {
        transform:
            scaleY(1);

        filter:
            brightness(1.07);
    }
}


@keyframes rrSweep {

    0% {
        transform:
            translateX(-60px);
    }

    100% {
        transform:
            translateX(520px);
    }
}


@keyframes rrFlowShine {

    0% {
        transform:
            translateX(-45px);
    }

    100% {
        transform:
            translateX(280px);
    }
}


@keyframes rrAmbientGlow {

    0%,
    100% {
        transform:
            scale(1);

        opacity: 0.55;
    }

    50% {
        transform:
            scale(1.10);

        opacity: 0.82;
    }
}


@keyframes rrLivePulse {

    0%,
    100% {
        opacity: 0.55;

        transform:
            scale(0.85);
    }

    50% {
        opacity: 1;

        transform:
            scale(1.12);
    }
}


/* =========================================================
   RESPONSIVO
========================================================= */

@container (width < 900px) {

    .rr-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }
}


@container (width < 480px) {

    .rr-grid {
        grid-template-columns: 1fr;
    }

    .rr-resource {
        min-height: 140px;
    }
}


@container (height < 260px) {

    #routing-resource-panel {
        padding: 7px;
    }

    .rr-root {
        gap: 7px;
    }

    .rr-resource {
        padding: 8px;

        gap: 6px;
    }

    .rr-resource-main {
        grid-template-columns:
            68px minmax(0, 1fr);

        gap: 8px;
    }

    .rr-gauge-value {
        font-size: 13px;
    }

    .rr-pulse-grid {
        inset:
            8px 7px
            7px 7px;
    }
}

options.onInit:
// Sets the text from customProperties
const htmlgraphicsText = htmlNode.getElementById('htmlgraphics-text');

if (htmlgraphicsText) {
  htmlgraphicsText.textContent = customProperties.text;

  // Change the text color based on the theme
  if (theme.isDark) {
    htmlgraphicsText.style.color = 'green';
  } else {
    htmlgraphicsText.style.color = 'red';
  }
}

options.onRender:
(function () {
    "use strict";

    const container =
        htmlNode.querySelector(
            "#routing-resource-panel"
        );

    if (!container) return;


    /* =====================================================
       ÍCONES (SVG inline - CDN de ícones não carrega
       dentro do sandbox deste painel)
    ===================================================== */

    const ICONS = {

        server:
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="3" width="20" height="7" rx="1.5"/><rect x="2" y="14" width="20" height="7" rx="1.5"/><line x1="6" y1="6.5" x2="6.01" y2="6.5"/><line x1="6" y1="17.5" x2="6.01" y2="17.5"/></svg>',

        cpu:
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="16" height="16" rx="2"/><rect x="9" y="9" width="6" height="6"/><line x1="9" y1="1" x2="9" y2="4"/><line x1="15" y1="1" x2="15" y2="4"/><line x1="9" y1="20" x2="9" y2="23"/><line x1="15" y1="20" x2="15" y2="23"/><line x1="20" y1="9" x2="23" y2="9"/><line x1="20" y1="14" x2="23" y2="14"/><line x1="1" y1="9" x2="4" y2="9"/><line x1="1" y1="14" x2="4" y2="14"/></svg>',

        mem:
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="7" width="20" height="10" rx="1.5"/><line x1="6" y1="7" x2="6" y2="4"/><line x1="10" y1="7" x2="10" y2="4"/><line x1="14" y1="7" x2="14" y2="4"/><line x1="18" y1="7" x2="18" y2="4"/><line x1="6" y1="17" x2="6" y2="20"/><line x1="18" y1="17" x2="18" y2="20"/></svg>',

        swap:
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M4 8h13"/><polyline points="13 4 17 8 13 12"/><path d="M20 16H7"/><polyline points="11 20 7 16 11 12"/></svg>',

        disk:
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v6c0 1.66 4.03 3 9 3s9-1.34 9-3V5"/><path d="M3 11v6c0 1.66 4.03 3 9 3s9-1.34 9-3v-6"/></svg>',

        bulb:
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18h6"/><path d="M10 22h4"/><path d="M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.3h6c0-1 .4-1.8 1-2.3A7 7 0 0 0 12 2z"/></svg>',

        info:
            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><line x1="12" y1="11" x2="12" y2="16"/><circle cx="12" cy="7.6" r="0.9" fill="currentColor" stroke="none"/></svg>'
    };


    /* =====================================================
       CONFIG
    ===================================================== */

    const CONFIG = {

        cpu: {
            label: "CPU",

            icon: "cpu",

            warning: 70,
            critical: 90
        },

        mem: {
            label: "Memória Real",

            icon: "mem",

            warning: 70,
            critical: 90
        },

        swap: {
            label: "Memória Virtual",

            icon: "swap",

            warning: 70,
            critical: 90
        },

        disk: {
            label: "Disco Local (/)",

            icon: "disk",

            warning: 70,
            critical: 90
        }
    };


    const panelData =
        typeof htmlGraphics !== "undefined" &&
        htmlGraphics &&
        htmlGraphics.data
            ? htmlGraphics.data
            : typeof data !== "undefined"
                ? data
                : null;


    /* =====================================================
       HELPERS
    ===================================================== */

    function normalizeText(value) {

        return String(value || "")
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "")
            .toLowerCase()
            .replace(/\s+/g, " ")
            .trim();
    }


    function escapeHTML(value) {

        return String(
            value == null
                ? ""
                : value
        ).replace(
            /[&<>"']/g,
            function (character) {

                return {
                    "&": "&amp;",
                    "<": "&lt;",
                    ">": "&gt;",
                    '"': "&quot;",
                    "'": "&#039;"
                }[character];
            }
        );
    }


    function toNumber(value) {

        if (
            value === null ||
            value === undefined ||
            value === ""
        ) {
            return null;
        }


        if (
            typeof value === "number"
        ) {

            return Number.isFinite(value)
                ? value
                : null;
        }


        const parsed =
            Number(
                String(value)
                    .replace("%", "")
                    .replace(",", ".")
                    .trim()
            );


        return Number.isFinite(parsed)
            ? parsed
            : null;
    }


    function getValues(field) {

        if (
            !field ||
            field.values === undefined ||
            field.values === null
        ) {
            return [];
        }


        if (
            Array.isArray(
                field.values
            )
        ) {

            return field.values;
        }


        if (
            typeof field.values.toArray ===
            "function"
        ) {

            return field.values.toArray();
        }


        const length =
            field.values.length ||
            field.values.size ||
            (
                field.values.buffer
                    ? field.values.buffer.length
                    : 0
            ) ||
            0;


        const output = [];


        for (
            let index = 0;
            index < length;
            index++
        ) {

            output.push(
                typeof field.values.get ===
                    "function"
                    ? field.values.get(index)
                    : field.values[index]
            );
        }


        return output;
    }


    function clamp(
        value,
        min,
        max
    ) {

        return Math.max(
            min,
            Math.min(
                max,
                value
            )
        );
    }


    /* =====================================================
       STATUS
    ===================================================== */

    function getStatus(
        value,
        config
    ) {

        if (
            value === null
        ) {

            return {
                className: "unknown",
                label: "Sem dados"
            };
        }


        if (
            value >=
            config.critical
        ) {

            return {
                className: "bad",
                label: "Crítico"
            };
        }


        if (
            value >=
            config.warning
        ) {

            return {
                className: "warn",
                label: "Atenção"
            };
        }


        return {
            className: "ok",
            label: "Normal"
        };
    }


    /* =====================================================
       COLETA
    ===================================================== */

    function readMetrics() {

        const metrics = {

            cpu: null,
            mem: null,
            swap: null,
            disk: null
        };


        if (
            !panelData ||
            !Array.isArray(
                panelData.series
            )
        ) {

            return metrics;
        }


        panelData.series.forEach(
            function (series) {

                const fields =
                    Array.isArray(
                        series.fields
                    )
                        ? series.fields
                        : [];


                let nameField =
                    fields.find(
                        function (field) {

                            const name =
                                normalizeText(
                                    field.name
                                );


                            return (
                                name === "field" ||
                                name === "metric" ||
                                name === "item" ||
                                name === "name"
                            );
                        }
                    );


                if (!nameField) {

                    nameField =
                        fields.find(
                            function (field) {

                                return (
                                    field.type ===
                                    "string"
                                );
                            }
                        );
                }


                let valueField =
                    fields.find(
                        function (field) {

                            if (
                                field ===
                                nameField
                            ) {
                                return false;
                            }


                            const name =
                                normalizeText(
                                    field.name
                                );


                            return (
                                name.startsWith(
                                    "last"
                                ) ||
                                name === "value" ||
                                name === "valor"
                            );
                        }
                    );


                if (!valueField) {

                    valueField =
                        fields.find(
                            function (field) {

                                return (
                                    field !==
                                        nameField &&
                                    field.type !==
                                        "time"
                                );
                            }
                        );
                }


                /* ===============================
                   FORMATO TABLE
                =============================== */

                if (
                    nameField &&
                    valueField
                ) {

                    const names =
                        getValues(
                            nameField
                        );


                    const values =
                        getValues(
                            valueField
                        );


                    const total =
                        Math.min(
                            names.length,
                            values.length
                        );


                    for (
                        let index = 0;
                        index < total;
                        index++
                    ) {

                        const name =
                            normalizeText(
                                names[index]
                            );


                        const value =
                            toNumber(
                                values[index]
                            );


                        if (
                            value === null
                        ) {

                            continue;
                        }


                        if (
                            name.includes(
                                "cpu utilization"
                            )
                        ) {

                            metrics.cpu =
                                value;

                            continue;
                        }


                        if (
                            name.includes(
                                "memory utilization"
                            )
                        ) {

                            metrics.mem =
                                value;

                            continue;
                        }


                        if (
                            name.includes(
                                "swap utilization"
                            )
                        ) {

                            metrics.swap =
                                value;

                            continue;
                        }


                        if (
                            name.includes(
                                "disk utilization"
                            )
                        ) {

                            metrics.disk =
                                value;
                        }
                    }


                    return;
                }


                /* ===============================
                   FALLBACK WIDE SERIES
                =============================== */

                fields.forEach(
                    function (field) {

                        if (
                            !field ||
                            field.type ===
                            "time"
                        ) {

                            return;
                        }


                        const name =
                            normalizeText(
                                [
                                    field.name,

                                    field.config
                                        ? field.config.displayName
                                        : "",

                                    field.config
                                        ? field.config.displayNameFromDS
                                        : ""
                                ]
                                    .filter(Boolean)
                                    .join(" ")
                            );


                        const values =
                            getValues(
                                field
                            );


                        let last =
                            null;


                        for (
                            let index =
                                values.length - 1;

                            index >= 0;

                            index--
                        ) {

                            const parsed =
                                toNumber(
                                    values[index]
                                );


                            if (
                                parsed !== null
                            ) {

                                last =
                                    parsed;

                                break;
                            }
                        }


                        if (
                            last === null
                        ) {

                            return;
                        }


                        if (
                            name.includes(
                                "cpu utilization"
                            )
                        ) {

                            metrics.cpu =
                                last;
                        }


                        if (
                            name.includes(
                                "memory utilization"
                            )
                        ) {

                            metrics.mem =
                                last;
                        }


                        if (
                            name.includes(
                                "swap utilization"
                            )
                        ) {

                            metrics.swap =
                                last;
                        }


                        if (
                            name.includes(
                                "disk utilization"
                            )
                        ) {

                            metrics.disk =
                                last;
                        }
                    }
                );
            }
        );


        return metrics;
    }


    /* =====================================================
       INSIGHT / REL-GIO
    ===================================================== */

    function formatNow() {

        const date =
            new Date();

        const dd =
            String(date.getDate())
                .padStart(2, "0");

        const mm =
            String(date.getMonth() + 1)
                .padStart(2, "0");

        const hh =
            String(date.getHours())
                .padStart(2, "0");

        const mi =
            String(date.getMinutes())
                .padStart(2, "0");

        return dd + "/" + mm + " " + hh + ":" + mi;
    }


    function buildInsight(metrics) {

        const entries =
            Object.keys(CONFIG)
                .map(function (type) {

                    return {
                        type: type,
                        value: metrics[type]
                    };
                })
                .filter(function (entry) {

                    return (
                        entry.value !== null
                    );
                });


        if (!entries.length) {

            return "Sem dados suficientes para gerar um insight no momento.";
        }


        entries.sort(
            function (a, b) {

                return b.value - a.value;
            }
        );


        const top =
            entries[0];

        const config =
            CONFIG[top.type];

        const valueText =
            top.value.toLocaleString(
                "pt-BR",
                {
                    maximumFractionDigits: 1
                }
            );


        return "Maior utilização agora: " + config.label + " em " + valueText + "%. Acompanhe se o valor continuar subindo.";
    }


    /* =====================================================
       ANIMA?fO
    ===================================================== */

    const WAVE_PHASE = {
        cpu: 0.5,
        mem: 1.6,
        swap: 2.7,
        disk: 3.8
    };


    function buildPulseBars(
        value,
        type
    ) {

        const safe =
            value === null
                ? 0
                : clamp(
                    value,
                    0,
                    100
                );


        const totalBars =
            16;


        let html =
            "";


        for (
            let index = 0;
            index < totalBars;
            index++
        ) {

            /*
             * O desenho NfO representa histórico.
             * ? apenas uma animação visual baseada
             * no percentual atual.
             */

            const position =
                index /
                (
                    totalBars - 1
                );


            /*
             * Forma de onda decorativa.
             */

            const wave =
                (
                    Math.sin(
                        (
                            position *
                            Math.PI *
                            3
                        ) +
                        (
                            WAVE_PHASE[type] ||
                            0
                        )
                    ) +
                    1
                ) /
                2;


            /*
             * Intensidade proporcional
             * ao percentual atual.
             */

            const intensity =
                safe /
                100;


            const minHeight =
                14;


            const dynamicHeight =
                minHeight +
                (
                    74 *
                    wave *
                    (
                        0.20 +
                        intensity *
                        0.80
                    )
                );


            const baseHeight =
                Math.max(
                    7,
                    dynamicHeight *
                    0.30
                );


            const pulseHeight =
                Math.max(
                    10,
                    dynamicHeight
                );


            const duration =
                1.5 +
                (
                    (
                        index *
                        0.11
                    ) %
                    1.4
                );


            const delay =
                -(
                    index *
                    0.075
                );


            html += `
                <span
                    class="rr-pulse"

                    style="
                        height:${Math.min(
                            100,
                            pulseHeight
                        )}%;

                        --base-height:${
                            Math.min(
                                100,
                                baseHeight
                            )
                        }%;

                        --pulse-height:${
                            Math.min(
                                100,
                                pulseHeight
                            )
                        }%;

                        --pulse-duration:
                            ${duration}s;

                        --pulse-delay:
                            ${delay}s;
                    "
                ></span>
            `;
        }


        return html;
    }


    /* =====================================================
       POPOVER DE RESUMO DA M?TRICA
    ===================================================== */

    function buildMetricPopover(type, value) {

        const config = CONFIG[type];
        const status = getStatus(value, config);

        const valueText =
            value === null
                ? "--"
                : value.toLocaleString("pt-BR", {
                    minimumFractionDigits: 0,
                    maximumFractionDigits: 1
                });

        return `
            <div class="rr-metric-popover" data-metric-popover="${type}">
                <strong>Resumo ${escapeHTML(config.label)}</strong>

                <div class="rr-metric-list">
                    <div class="rr-metric-row"><span>Atual</span><strong>${escapeHTML(valueText)}%</strong></div>
                    <div class="rr-metric-row"><span>Status</span><strong>${escapeHTML(status.label)}</strong></div>
                    <div class="rr-metric-row"><span>Aviso &ge;</span><strong>${config.warning}%</strong></div>
                    <div class="rr-metric-row"><span>Cr&iacute;tico &ge;</span><strong>${config.critical}%</strong></div>
                </div>
            </div>
        `;
    }


    /* =====================================================
       CARD
    ===================================================== */

    function buildResource(
        type,
        value
    ) {

        const config =
            CONFIG[type];


        const status =
            getStatus(
                value,
                config
            );


        const safe =
            value === null
                ? 0
                : clamp(
                    value,
                    0,
                    100
                );


        const valueText =
            value === null
                ? "--"
                : value.toLocaleString(
                    "pt-BR",
                    {
                        minimumFractionDigits:
                            0,

                        maximumFractionDigits:
                            1
                    }
                );


        /*
         * Linha dentro da animação.
         * Como o gráfico tem padding,
         * limitamos visualmente a posição.
         */

        const currentLevel =
            Math.max(
                9,
                Math.min(
                    88,
                    safe
                )
            );


        return `
            <article
                class="
                    rr-resource
                    ${type}
                "
            >

                <!-- HEADER DO RECURSO -->

                <div
                    class="rr-resource-header"
                >

                    <div
                        class="rr-resource-name"
                    >

                        <div
                            class="rr-resource-icon"
                        >
                            ${ICONS[config.icon]}
                        </div>


                        <div
                            class="rr-resource-title"
                        >

                            <strong>
                                ${escapeHTML(
                                    config.label
                                )}
                            </strong>

                        </div>

                    </div>


                    <button
                        class="rr-metric-btn"
                        data-metric-btn="${type}"
                        title="Resumo da métrica"
                    >
                        ${ICONS.info}
                    </button>

                </div>


                <!-- CENTRO -->

                <div
                    class="rr-resource-main"
                >

                    <!-- VALOR -->

                    <div
                        class="rr-value-area"
                    >

                        <div
                            class="rr-gauge"

                            style="
                                --value:
                                ${safe};
                            "
                        >
                            <span
                                class="rr-gauge-value"
                            >
                                ${escapeHTML(
                                    valueText
                                )}<small>%</small>
                            </span>
                        </div>


                        <div
                            class="
                                rr-resource-status
                                ${status.className}
                            "
                        >
                            ${escapeHTML(
                                status.label
                            )}
                        </div>

                    </div>


                    <!-- ANIMA?fO -->

                    <div
                        class="rr-animation-area"
                    >

                        <div
                            class="rr-pulse-grid"
                        >
                            ${buildPulseBars(
                                value,
                                type
                            )}
                        </div>


                        <div
                            class="rr-current-line"

                            style="
                                --current-level:
                                ${currentLevel}%;
                            "
                        ></div>

                    </div>

                </div>


                <!-- BARRA INFERIOR -->

                <div
                    class="rr-flow"
                >

                    <div
                        class="rr-flow-header"
                    >

                        <span>
                            Capacidade
                        </span>


                        <strong>
                            ${escapeHTML(
                                valueText
                            )}%
                        </strong>

                    </div>


                    <div
                        class="rr-flow-track"
                    >

                        <span
                            class="
                                rr-threshold
                                t70
                            "
                        ></span>


                        <span
                            class="
                                rr-threshold
                                t90
                            "
                        ></span>


                        <div
                            class="rr-flow-fill"

                            style="
                                --resource-progress:
                                ${safe}%;
                            "
                        ></div>

                    </div>

                </div>

            </article>
        `;
    }


    /* =====================================================
       MAIN
    ===================================================== */

    function main() {

        if (
            !panelData ||
            !panelData.series ||
            !panelData.series.length
        ) {

            container.innerHTML = `
                <div
                    class="rr-empty"
                >
                    Aguardando dados de CPU, memória, swap e disco...
                </div>
            `;

            return;
        }


        const metrics =
            readMetrics();


        const insightText =
            buildInsight(metrics);


        container.innerHTML = `

            <div
                class="rr-root"
            >

                <!-- HEADER -->

                <header
                    class="rr-header"
                >

                    <div
                        class="rr-header-left"
                    >

                        <div
                            class="rr-header-icon"
                        >
                            ${ICONS.server}
                        </div>


                        <div
                            class="rr-header-text"
                        >

                            <strong>
                                Performance do Host
                            </strong>


                            <span>
                                CPU, memória, swap e disco
                            </span>

                        </div>

                    </div>


                    <div
                        class="rr-actions"
                    >

                        <div
                            class="rr-refresh"
                        >
                            Atualizado ${formatNow()}
                        </div>


                        <button
                            class="rr-insight-btn"
                            id="rr-insight-btn"
                            title="Insight rápido"
                        >
                            ${ICONS.bulb}
                        </button>

                    </div>


                    <div
                        class="rr-insight-popover"
                        id="rr-insight-popover"
                    >
                        <strong>
                            Insight rápido
                        </strong>

                        <span>
                            ${escapeHTML(
                                insightText
                            )}
                        </span>
                    </div>

                </header>


                <!-- RECURSOS -->

                <section
                    class="rr-grid"
                >

                    ${buildResource(
                        "cpu",
                        metrics.cpu
                    )}


                    ${buildResource(
                        "mem",
                        metrics.mem
                    )}


                    ${buildResource(
                        "swap",
                        metrics.swap
                    )}


                    ${buildResource(
                        "disk",
                        metrics.disk
                    )}

                </section>


                ${buildMetricPopover(
                    "cpu",
                    metrics.cpu
                )}


                ${buildMetricPopover(
                    "mem",
                    metrics.mem
                )}


                ${buildMetricPopover(
                    "swap",
                    metrics.swap
                )}


                ${buildMetricPopover(
                    "disk",
                    metrics.disk
                )}

            </div>
        `;


        const insightBtn =
            container.querySelector(
                "#rr-insight-btn"
            );

        const insightPopover =
            container.querySelector(
                "#rr-insight-popover"
            );


        if (
            insightBtn &&
            insightPopover
        ) {

            insightBtn.addEventListener(
                "click",
                function (event) {

                    event.stopPropagation();

                    insightPopover.classList.toggle(
                        "open"
                    );
                }
            );


            container.addEventListener(
                "click",
                function (event) {

                    if (
                        !event.target.closest(
                            "#rr-insight-popover"
                        ) &&
                        !event.target.closest(
                            "#rr-insight-btn"
                        )
                    ) {

                        insightPopover.classList.remove(
                            "open"
                        );
                    }
                }
            );
        }


        const rootEl = container.querySelector(".rr-root");

        container.querySelectorAll("[data-metric-btn]").forEach(function (button) {
            button.addEventListener("click", function (event) {
                event.stopPropagation();

                const type = button.dataset.metricBtn;
                const target = container.querySelector('[data-metric-popover="' + type + '"]');

                container.querySelectorAll(".rr-metric-popover.open").forEach(function (el) {
                    if (el !== target) el.classList.remove("open");
                });

                if (insightPopover) insightPopover.classList.remove("open");

                if (!target || !rootEl) return;

                const willOpen = !target.classList.contains("open");
                target.classList.toggle("open");

                if (willOpen) {
                    const btnRect = button.getBoundingClientRect();
                    const rootRect = rootEl.getBoundingClientRect();

                    let top = btnRect.bottom - rootRect.top + 6;
                    let left = btnRect.right - rootRect.left - target.offsetWidth;

                    left = Math.max(4, Math.min(left, rootRect.width - target.offsetWidth - 4));

                    target.style.top = top + "px";
                    target.style.left = left + "px";
                }
            });
        });

        container.addEventListener("click", function (event) {
            if (!event.target.closest(".rr-metric-popover") && !event.target.closest(".rr-metric-btn")) {
                container.querySelectorAll(".rr-metric-popover.open").forEach(function (el) {
                    el.classList.remove("open");
                });
            }
        });
    }


    main();

})();

